<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/auth.php';
require_once __DIR__ . '/../config/telefono.php';
require_once __DIR__ . '/../config/reglas-acceso.php';
$me=page_require(['ADMIN','VERIFICADOR']);$admin=($me['rol']??'')==='ADMIN';
$config = require __DIR__ . '/../config/database.php';
$pdo = new PDO("mysql:host={$config['host']};dbname={$config['dbname']};charset={$config['charset']}",$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
$id = trim((string)filter_input(INPUT_GET, 'id', FILTER_DEFAULT));if (!preg_match('/^[a-f0-9-]{36}$/i', $id)) { http_response_code(400); exit('Alumno no especificado.'); }
$sedeClave=auth_active_sede_clave();$stmt=$pdo->prepare("SELECT id FROM sedes WHERE clave=:clave AND activo=1 LIMIT 1");$stmt->execute([':clave'=>$sedeClave]);$sedeId=(string)$stmt->fetchColumn();if($sedeId===''){http_response_code(422);exit('Sede activa inválida.');}
$sql = "SELECT a.id,a.nombre,a.fecha_nacimiento,a.whatsapp,a.correo,a.fecha_inicio,a.estado_administrativo,a.observaciones,a.ciclo_pago,a.plan_programado_desde,s.nombre AS sede_nombre,h.hora_inicio,h.hora_fin,p.nombre AS plan_nombre,p.sesiones_semana,p.precio,pp.nombre AS plan_programado_nombre,pp.sesiones_semana AS plan_programado_sesiones,pp.precio AS plan_programado_precio FROM alumnos a INNER JOIN sedes s ON s.id=a.sede_id LEFT JOIN horarios h ON h.id=a.horario_preferido_id AND h.sede_id=a.sede_id LEFT JOIN planes p ON p.id=a.plan_actual_id AND p.sede_id=a.sede_id LEFT JOIN planes pp ON pp.id=a.plan_programado_id AND pp.sede_id=a.sede_id WHERE a.id=:id AND a.sede_id=:sede LIMIT 1";$stmt=$pdo->prepare($sql);$stmt->execute([':id'=>$id,':sede'=>$sedeId]);$alumno=$stmt->fetch();if(!$alumno){http_response_code(404);exit('Alumno no encontrado.');}
$historica=regla_inscripcion_historica_cubierta($pdo,(string)$alumno['id']);
function e(?string $valor):string{return htmlspecialchars($valor??'',ENT_QUOTES,'UTF-8');}function fecha(?string $valor):string{return !empty($valor)?date('d/m/Y',strtotime($valor)):'—';}function hora(?string $valor):string{return !empty($valor)?date('H:i',strtotime($valor)):'—';}
function telefono_visible(?string $valor):string{$v=trim((string)$valor);if($v==='')return '—';if(!telefono_es_e164($v))return $v.' · país sin verificar';$d=telefono_descomponer($v);$p=telefono_paises();$codigo=$d['pais']!==''?($p[$d['pais']]['codigo']??''):'';return $codigo!==''?$codigo.' '.$d['nacional']:$v;}
function clase_estado(string $estado):string{return match($estado){'ACTIVO'=>'activo','BAJA'=>'baja',default=>'pendiente'};}
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Ficha de <?=e($alumno['nombre'])?></title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f3f6fa;color:#172033}.contenedor{max-width:980px;margin:0 auto;padding:30px 20px}.encabezado{margin-bottom:25px}.encabezado a{color:#2563eb;text-decoration:none;font-size:14px}.encabezado h1{margin:12px 0 5px;font-size:30px}.subtitulo{color:#64748b}.tarjeta{background:white;border-radius:18px;padding:25px;margin-bottom:18px;box-shadow:0 4px 18px rgba(0,0,0,.06)}.titulo{font-size:18px;font-weight:bold;margin-bottom:20px}.datos{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.dato{padding:14px;background:#f8fafc;border-radius:10px}.etiqueta{display:block;font-size:12px;color:#64748b;margin-bottom:5px}.valor{font-size:16px;font-weight:600}.valor.secundario{font-size:14px;color:#475569}.estado{display:inline-block;padding:6px 12px;border-radius:999px;font-size:13px;font-weight:bold}.activo{background:#dcfce7;color:#166534}.baja{background:#fee2e2;color:#991b1b}.pendiente{background:#fef3c7;color:#92400e}.historica{background:#e0f2fe;color:#075985}.observaciones{white-space:pre-wrap;line-height:1.6;color:#475569}.acciones{margin-top:15px;display:flex;gap:9px;flex-wrap:wrap}.boton-editar,.boton-eliminar,.boton-secundario{display:inline-block;padding:10px 16px;border:0;border-radius:10px;text-decoration:none!important;font-weight:700;cursor:pointer}.boton-editar{background:#2563eb;color:white!important}.boton-secundario{background:#e2e8f0;color:#172033!important}.boton-eliminar{background:#fee2e2;color:#991b1b}.timeline{display:grid;gap:12px}.evento{border-left:4px solid #cbd5e1;background:#f8fafc;border-radius:12px;padding:13px 15px}.evento-top{display:flex;justify-content:space-between;gap:10px;align-items:flex-start}.evento-tipo{font-size:11px;font-weight:900;letter-spacing:.06em;text-transform:uppercase;color:#64748b}.evento-fecha{font-size:12px;color:#64748b;white-space:nowrap}.evento-titulo{font-weight:800;margin-top:5px}.evento-detalle{font-size:13px;color:#475569;line-height:1.45;margin-top:5px}.evento-link{display:inline-block;margin-top:7px;font-size:13px;font-weight:700;color:#2563eb;text-decoration:none}.timeline-estado{padding:12px;background:#f8fafc;border-radius:10px;color:#64748b}.dato-desconocido{color:#64748b;font-size:14px;font-weight:600}.modal{display:none;position:fixed;inset:0;background:#0f172a88;z-index:1000;padding:20px;align-items:center;justify-content:center}.modal.abierto{display:flex}.modal-card{width:min(500px,100%);background:white;border-radius:18px;padding:24px;box-shadow:0 24px 70px #0004}.modal-card h2{margin:0 0 10px;color:#991b1b}.modal-card p,.modal-card li{color:#475569;line-height:1.5}.modal-card ul{padding-left:20px}.modal-card label{display:block;font-weight:800;margin:18px 0 7px}.modal-card input{width:100%;padding:13px;border:1px solid #cbd5e1;border-radius:10px;font-size:16px}.modal-actions{display:flex;justify-content:flex-end;gap:9px;margin-top:18px}.modal-actions button{border:0;border-radius:10px;padding:11px 14px;font-weight:800;cursor:pointer}.cancelar{background:#e2e8f0;color:#172033}.confirmar{background:#b91c1c;color:#fff}.confirmar:disabled{opacity:.6}.error-delete{min-height:20px;color:#b91c1c;font-weight:700;margin-top:10px;font-size:13px}@media(max-width:650px){.datos{grid-template-columns:1fr}.encabezado h1{font-size:25px}.tarjeta{padding:18px}.contenedor{padding-top:72px}.evento-top{display:block}.evento-fecha{margin-top:4px}}</style></head><body><div class="contenedor"><div class="encabezado"><a href="alumnos.php">← Volver a alumnos</a><div class="acciones"><?php if($admin):?><a class="boton-editar" href="editar-alumno.php?id=<?=urlencode($alumno['id'])?>">Editar alumno</a><?php endif;?><a class="boton-secundario" href="pagos.php?alumno_id=<?=urlencode($alumno['id'])?>">Ver pagos</a><?php if($admin):?><button type="button" class="boton-eliminar" id="abrirEliminar">Eliminar definitivamente</button><?php endif;?></div><h1><?=e($alumno['nombre'])?></h1><div class="subtitulo">Expediente 360° · ID <?=e((string)$alumno['id'])?></div></div><div class="tarjeta"><div class="titulo">Información personal</div><div class="datos"><div class="dato"><span class="etiqueta">Nombre</span><span class="valor"><?=e($alumno['nombre'])?></span></div><div class="dato"><span class="etiqueta">Fecha de nacimiento</span><span class="valor"><?=fecha($alumno['fecha_nacimiento'])?></span></div><div class="dato"><span class="etiqueta">WhatsApp</span><span class="valor"><?=e(telefono_visible($alumno['whatsapp']))?></span></div><div class="dato"><span class="etiqueta">Correo</span><span class="valor"><?=e($alumno['correo'])?:'—'?></span></div></div></div><div class="tarjeta"><div class="titulo">Situación actual</div><div class="datos"><div class="dato"><span class="etiqueta">Sede</span><span class="valor"><?=e($alumno['sede_nombre'])?></span></div><div class="dato"><span class="etiqueta">Estado administrativo</span><span class="estado <?=clase_estado((string)$alumno['estado_administrativo'])?>"><?=e($alumno['estado_administrativo'])?></span></div><div class="dato"><span class="etiqueta">Fecha de inicio</span><span class="valor"><?=fecha($alumno['fecha_inicio'])?></span></div><div class="dato"><span class="etiqueta">Ciclo de pago</span><span class="valor"><?=e($alumno['ciclo_pago'])?:'—'?></span></div><div class="dato"><span class="etiqueta">Horario regular</span><span class="valor"><?=hora($alumno['hora_inicio'])?> — <?=hora($alumno['hora_fin'])?></span></div><div class="dato"><span class="etiqueta">Plan actual</span><span class="valor"><?=e($alumno['plan_nombre'])?:'—'?></span><?php if($alumno['plan_nombre']!==null):?><div class="valor secundario"><?=e((string)$alumno['sesiones_semana'])?> sesiones/semana · $<?=number_format((float)$alumno['precio'],0)?></div><?php endif;?></div><div class="dato"><span class="etiqueta">Plan programado</span><span class="valor"><?=e($alumno['plan_programado_nombre'])?:'—'?></span><?php if($alumno['plan_programado_nombre']!==null):?><div class="valor secundario">Desde <?=fecha($alumno['plan_programado_desde'])?> · <?=e((string)$alumno['plan_programado_sesiones'])?> sesiones/semana · $<?=number_format((float)$alumno['plan_programado_precio'],0)?></div><?php endif;?></div><div class="dato"><span class="etiqueta">Nivel académico</span><span class="dato-desconocido">No registrado en una fuente académica</span></div><div class="dato"><span class="etiqueta">Inscripción</span><?php if($historica):?><span class="estado historica">HISTÓRICA CUBIERTA</span><?php else:?><span class="valor">Según pagos registrados</span><?php endif;?></div></div></div><div class="tarjeta"><div class="titulo">Línea de tiempo</div><div id="timelineAlumno" class="timeline" aria-live="polite"><div class="timeline-estado">Cargando eventos…</div></div></div><div class="tarjeta"><div class="titulo">Observaciones actuales</div><div class="observaciones"><?=e($alumno['observaciones'])?:'Sin observaciones.'?></div><div class="valor secundario" style="margin-top:10px">Texto histórico sin autoría/fecha separada; no se presenta como nota auditada.</div></div></div><script>
const timelineAlumno=document.getElementById('timelineAlumno');
const escTimeline=v=>String(v??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot',"'":'&#39;'}[ch]));
function fechaTimeline(v){const d=String(v||'').slice(0,10).split('-');return d.length===3?`${d[2]}/${d[1]}/${d[0]}`:'—';}
async function cargarTimeline(){try{const r=await fetch('/api/timeline-alumno.php?alumno_id='+encodeURIComponent(<?=json_encode((string)$alumno['id'])?>)),d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'No se pudo cargar');const items=Array.isArray(d.items)?d.items:[];timelineAlumno.innerHTML=items.length?items.map(item=>`<article class="evento"><div class="evento-top"><div class="evento-tipo">${escTimeline(item.tipo)}</div><div class="evento-fecha">${fechaTimeline(item.fecha)}</div></div><div class="evento-titulo">${escTimeline(item.titulo)}</div>${item.detalle?`<div class="evento-detalle">${escTimeline(item.detalle)}</div>`:''}${item.href?`<a class="evento-link" href="${escTimeline(item.href)}">Abrir origen</a>`:''}</article>`).join(''):'<div class="timeline-estado">No hay eventos registrados para este alumno.</div>';}catch(err){timelineAlumno.innerHTML='<div class="timeline-estado">'+escTimeline(err.message||'No se pudo cargar la línea de tiempo.')+'</div>';}}
cargarTimeline();
</script>
<?php if($admin):?><div class="modal" id="modalEliminar" role="dialog" aria-modal="true" aria-labelledby="tituloEliminar"><div class="modal-card"><h2 id="tituloEliminar">Eliminar a <?=e($alumno['nombre'])?></h2><p>Esta acción borra definitivamente la ficha y toda la información operativa asociada:</p><ul><li>pagos, mensualidades e inscripciones;</li><li>participación en intensivos, asistencias, ausencias y reposiciones;</li><li>acceso al portal y registros relacionados.</li></ul><p><strong>No se puede deshacer.</strong> Si algún pago válido pertenece a un mes ya cerrado, el sistema bloqueará la eliminación para proteger la contabilidad.</p><form id="formEliminar"><label for="passwordEliminar">Tu contraseña de administrador</label><input type="password" id="passwordEliminar" required autocomplete="current-password"><div class="error-delete" id="errorEliminar" role="alert"></div><div class="modal-actions"><button type="button" class="cancelar" id="cancelarEliminar">Cancelar</button><button type="submit" class="confirmar" id="confirmarEliminar">Eliminar definitivamente</button></div></form></div></div><script>
const modalEliminar=document.getElementById('modalEliminar'),passwordEliminar=document.getElementById('passwordEliminar'),errorEliminar=document.getElementById('errorEliminar'),confirmarEliminar=document.getElementById('confirmarEliminar');
function cerrarEliminar(){modalEliminar.classList.remove('abierto');passwordEliminar.value='';errorEliminar.textContent='';}
document.getElementById('abrirEliminar').onclick=()=>{modalEliminar.classList.add('abierto');setTimeout(()=>passwordEliminar.focus(),50)};document.getElementById('cancelarEliminar').onclick=cerrarEliminar;modalEliminar.addEventListener('click',e=>{if(e.target===modalEliminar)cerrarEliminar()});
document.getElementById('formEliminar').addEventListener('submit',async e=>{e.preventDefault();errorEliminar.textContent='';confirmarEliminar.disabled=true;confirmarEliminar.textContent='Eliminando...';try{const r=await fetch('/api/alumno-gestion.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({accion:'ELIMINAR',alumno_id:<?=json_encode($alumno['id'])?>,password:passwordEliminar.value,csrf:<?=json_encode(auth_csrf_token())?>})});const d=await r.json();if(!r.ok||!d.ok)throw new Error(d.error||'No se pudo eliminar');location.href='/alumnos.php';}catch(err){errorEliminar.textContent=err.message||'No se pudo eliminar el alumno.';confirmarEliminar.disabled=false;confirmarEliminar.textContent='Eliminar definitivamente';}});
</script><?php endif;?></body></html>
